# -*- coding: utf-8 -*-
"""Phase 1 sheet data: Settings, Masters, HR Management."""

SETTINGS = [
 ["1.1", "User",
  "mst_user.php (list) > mst_users_add.php (add/edit) > mst_users_rights.php (screen rights)",
  "Master + permissions",
  "Every person who can log in. Name, email, mobile, login, password, photo, the BRANCH they work in, and whether they are an administrator. Rights are ticked on a second screen.",
  "tbl_user (RW)\ntbl_user_rights (RW - hard delete)\nmst_main_menu (R)\nmst_sub_menu (R)\nmst_branch (R)",
  "INSERT tbl_user - built by CIS_InsertRecord from the whole $_REQUEST, so the input name IS the column. usr_logpwd hashed; pw_hint holds the SAME password in clear.\nUPDATE tbl_user on edit (photo kept if none re-uploaded).\nRIGHTS SAVE: DELETE FROM tbl_user_rights WHERE usr_id = <user> - a HARD delete of every row - then INSERT one row per ticked screen (usr_id, mm_id, sm_id).\nDELETE: UPDATE tbl_user SET usr_status = 0. Rights rows are left behind.",
  "1. Settings > User - active users only (usr_status = 1).\n2. Add New opens mst_users_add.php.\n3. Name, email, mobile, login name, password; pick BRANCH and USER TYPE; optional photo.\n4. Save - first checks no other ACTIVE user has that email ('User details already exist').\n5. Password hashed as md5(password + fixed salt); photo written to project_img/usr_photo/.\n6. From the list, the rights icon opens mst_users_rights.php - every menu and screen as tick boxes, pre-ticked from tbl_user_rights.\n7. Tick / untick, Update. The sidebar changes on their next page load.",
  "The user's own sidebar (rebuilt from tbl_user_rights on every page load); the login screen; created_by / modify_by on everything they touch; every branch-aware screen, which reads their branch_id from the session to pick the right item columns.",
  "pw_hint stores the password IN CLEAR - anyone who can read tbl_user reads every password. The hash is md5 with one shared salt: also weak.\nRights are REBUILT, not amended: save deletes all rows first, so saving a half-loaded page silently strips rights.\nUniqueness is checked on EMAIL ONLY - two users can share a usr_logname.\nusr_type = 'A' bypasses tbl_user_rights entirely."],

 ["1.2", "Branch", "mst_branch.php (list + form in one file)", "Master - THE key table",
  "The three branches (HO, Kerala, Rajapalayam) with their letterhead - address, phones, email, GST, PAN. AND, far more importantly, the NAMES OF THE COLUMNS in tbl_item_stock that belong to each branch.",
  "mst_branch (RW)\ntbl_item_stock (not touched here, but every stored column name points into it)",
  "INSERT mst_branch (branch_name, branch_code, branch_state_code, company_address, created_by, created_dtm) - EVERY column-name field is left EMPTY.\nUPDATE mst_branch - the same four fields plus modify_by, modify_dtm.\nDELETE: UPDATE branch_status = 0.",
  "1. Settings > Branch - three rows.\n2. Add New or the pencil opens the same page with the form filled.\n3. The form asks for only FOUR things: branch name, branch code, state code, address.\n4. Save / Update. That is all the screen writes.\n5. The letterhead fields and all fifty column-name fields are NOT on this form - they were loaded when the database was built and are edited directly in the database.",
  "The top of every print (quotation, sales order, PO, GRN, invoice) reads the logged-in user's branch row for the letterhead; the branch dropdown on the user screen; EVERY stock figure in the system, indirectly - screens read branch_stock_field and build their SQL around whatever column name they find.",
  "ADDING A BRANCH HERE WILL NOT WORK. Four fields are saved and fifty column-name fields left empty, so the new branch has no stock column, no price column, no location columns. Adding one properly means ALTER TABLE tbl_item_stock plus setting all fifty names by hand. The repo still has the ALTER script that added Rajapalayam.\nRAJAPALAYAM'S TAX DETAILS LOOK WRONG: branch_state_code 33 (Tamil Nadu) but company_state_code 32 and Kerala's GST number - copied from the Kerala row. The state code decides CGST/SGST vs IGST.\nKey fields: branch_stock_field (ho_stock / kl_stock / rjpm_stock), branch_stock_location_rack_field, branch_stock_location_row_field, branch_item_* (current pricing), branch_new_* (proposed), branch_old_* (superseded) - 13 each."],

 ["1.3", "Common Settings", "mst_common_settings.php", "Switch board",
  "One question: for which suppliers should the item discount be applied automatically? Every approved supplier gets a tick box. Ticked, and picking their item on a quotation or invoice brings the discount in by itself.",
  "mst_supplier_new (RW - the discount_apply flag only)",
  "UPDATE mst_supplier_new SET discount_apply = 0 WHERE supp_type = 'S' AND supp_status = 1 - CLEARS THE FLAG ON EVERY ACTIVE SUPPLIER, always, first.\nUPDATE mst_supplier_new SET discount_apply = 1 WHERE supp_id IN (...) - only the ones you ticked.",
  "1. Settings > Common Settings - every active supplier listed with a tick box, pre-ticked from discount_apply.\n2. Tick and untick.\n3. Update - clear-all runs first, then the ticked ones are set.\n4. Live immediately: the next item picked on a quotation behaves the new way.",
  "Quotation and Invoice - the discount fills in by itself for a ticked supplier's items; inc/cis_ajax/jquery_select_item.php returns the flag alongside the item so the screen knows whether to apply it.",
  "THERE IS NO mst_common_settings TABLE. Despite the name this is only another way of editing one column on mst_supplier_new.\nUNTICK EVERYTHING AND UPDATE = automatic discounts off for the whole company, because the clear-all statement always runs first. Only suppliers visible and ticked at the moment you press Update keep the flag."],
]

MASTERS = [
 ["2.1", "Customers",
  "lst_customers.php (list) > mst_customer_new.php (add/edit) > inc/datatable/ajaxCustomerList.php (rows) > inc/cis_ajax/modal_supplier_dets.php (view)",
  "Master + child rows",
  "Companies you sell to. Main address, delivery address, bank details, GST and PAN - plus any number of BRANCHES (separate delivery points, each with its own contact and address). Saving also creates the customer's accounts ledger.",
  "mst_supplier_new (W, supp_type = 'C')\nmst_ledger (W - FIRST)\nmst_accounts_group (R)\nmst_customer_branch (RW)\nmst_customer_branch_temp (W - session staging)\nmst_state / mst_district / mst_city (R)",
  "INSERT mst_ledger FIRST (group_id, ledger_name, ledger_type from group_type, open_bal, open_bal_type) -> capture ledger_id.\nINSERT mst_supplier_new with supp_type = 'C', supp_code = 'C' + lpad(MAX(supp_id)+1, 4), ledger_id.\nDELETE FROM mst_customer_branch WHERE supp_id = <new id> - so the copy cannot double up.\nINSERT mst_customer_branch - one row per staged branch, now under the real supp_id.\nDELETE FROM mst_customer_branch_temp WHERE session_id = <yours>.\nEDIT: UPDATE mst_ledger + UPDATE mst_supplier_new together.\nDELETE: UPDATE supp_status = 0. THE LEDGER IS LEFT ALONE.",
  "1. Masters > Customers - active customers with their branches listed beside them.\n2. Add New opens mst_customer_new.php.\n3. Company details, then the main address: State -> District -> City, each dropdown reloading from the one above.\n4. Delivery address and bank details. Tick URP for an unregistered customer and the screen puts the literal text 'URP' into both GST and PAN.\n5. Choose the ACCOUNTS GROUP for the ledger, plus opening balance and its Dr/Cr side.\n6. Add branches - each goes straight into mst_customer_branch_temp against your session, not attached to the customer yet.\n7. Save - ledger, then code, then customer, then the staged branches copied across and the staging cleared.",
  "Quotation, Sales Order and Invoice - the customer dropdown and the branch dropdown under it; Delivery Challan - the delivery address comes from the chosen customer branch; Sales Receipt and every accounts report, through ledger_id; Credit List and the sales reports.",
  "THE CODE IS NOT SAFE FOR TWO PEOPLE AT ONCE: it is MAX(supp_id)+1 computed BEFORE the insert, and the column is not unique, so simultaneous saves get the same code.\nCustomer and supplier codes SHARE one counter - the maximum is over the whole table, not over supp_type = 'C'.\nsupp_code and supp_id can drift apart; trust supp_id for identity.\nThe customer list is NOT filtered by branch - every branch sees every customer (unlike suppliers)."],

 ["2.2", "Supplier",
  "lst_supplier.php (list) > mst_supplier_new.php (add/edit) > mst_supplier_approve.php (approve) > inc/datatable/ajaxSupplierList.php",
  "Master + approval",
  "Companies you buy from. The customer form's twin plus CREDIT DAYS and PAYMENT MODE - and an approval step: a new supplier is unapproved, and purchase screens will not offer them until someone confirms.",
  "mst_supplier_new (RW, supp_type = 'S')\nmst_ledger (W - FIRST)\nmst_accounts_group (R)\nmst_finyear (R - goes into the code)\nmst_branch (R - goes into the code)\nmst_state / mst_district / mst_city (R)",
  "INSERT mst_ledger FIRST -> capture ledger_id.\nINSERT mst_supplier_new: supp_type = 'S', company_branch_id = YOUR branch, supp_credit_days, supp_pay_mode, ledger_id, and supp_code = 'S/0042/BIE/HO/2025-26'. supp_approve_status stays 0.\nEDIT: UPDATE mst_ledger + UPDATE mst_supplier_new (code never changes).\nAPPROVE: UPDATE mst_supplier_new SET supp_approve_status = 1, supp_approve_by = <usr_id>, supp_approve_dt = NOW.\nCOMMON SETTINGS: UPDATE discount_apply.\nDELETE: UPDATE supp_status = 0.",
  "1. Masters > Supplier - the list shows an approved / not-approved column.\n2. Add New opens mst_supplier_new.php. Company, address, bank, GST, PAN, plus credit days and payment mode.\n3. Accounts group and opening balance for the ledger.\n4. Save - ledger first, then the code, then the supplier stamped with YOUR branch as company_branch_id.\n5. From the list, open the approve action - mst_supplier_approve.php shows the supplier read-only with an Approve button.\n6. Approve - supp_approve_status becomes 1, with your user id and the timestamp.\n7. The supplier now appears in the Purchase Order and GRN dropdowns.",
  "Purchase Order and Direct PO - approved suppliers only; GRN (and the credit days that set the due date); GRN Payment Details, through the ledger; Item Details - a supplier can be linked to an item as its source; Common Settings tick list; Cost Worksheet and purchase reports.",
  "WHO SEES WHICH SUPPLIERS: user id 1 OR anyone whose branch is Head Office sees everything; every other branch sees only suppliers with their own company_branch_id. A Kerala buyer genuinely cannot see a Rajapalayam supplier.\nAPPROVAL IS ONE CLICK WITH NO SECOND PAIR OF EYES - the person who added the supplier can approve them, and editing an approved supplier (bank details included) does NOT reset the approval.\nOn edit the ledger is updated with the ledger_id POSTED BY THE FORM, not the one read back from the supplier row (the code fetches the right one and then does not use it)."],

 ["2.3", "Box Type", "mst_boxtype.php", "Lookup",
  "The kinds of packing box a delivery challan can be packed into - Corrugated Box, Wooden Box and so on.",
  "tbl_dc_package_box (RW)",
  "INSERT tbl_dc_package_box (box_name); box_status defaults to 1.\nUPDATE box_name on edit.\nDELETE: UPDATE box_status = 0.",
  "1. Open the screen - live box types listed.\n2. Type a name, Save.\n3. The pencil loads the row back into the same form.\n4. It now appears in the Delivery Challan packing section.",
  "Delivery Challan - the packing section, where each box on the challan picks a type from here.",
  "Three columns only: box_id, box_name, box_status. Renaming changes the name shown on old challans too, because the challan stores the id and looks the name up at print time."],

 ["2.4", "State", "mst_state.php", "Lookup (address level 1)",
  "The states, with their GST state codes. Top of the three-level address list, and the source of the code that decides CGST+SGST versus IGST.",
  "mst_state (RW)",
  "INSERT mst_state (state_name, state_shname, state_code, country_id).\nUPDATE all on edit.\nDELETE: UPDATE state_status = 0.",
  "1. Open - live states listed.\n2. Enter name, short name and the GST state code, Save.\n3. The pencil loads the row for correction.\n4. It now appears in the first dropdown of every address block.",
  "Every address block in the system - customer, supplier, employee, delivery. Also the tax calculation on quotations and invoices. Feeds the District screen.",
  "Changing a state_code RETROSPECTIVELY changes how old invoices reprint, because the print reads it live rather than storing it on the invoice. Verify once at setup, then leave alone."],

 ["2.5", "District", "mst_district.php", "Lookup (address level 2)",
  "Districts, each belonging to one state. The middle level.",
  "mst_district (RW)\nmst_state (R)",
  "INSERT mst_district (district_name, state_id, country_id).\nUPDATE name and state on edit.\nDELETE: UPDATE district_status = 0.",
  "1. Open - live districts listed with their state.\n2. Choose State, type District, Save.\n3. Edit can rename it or move it to another state.\n4. It now appears whenever that state is chosen in an address block.",
  "The District dropdown on every address block, reloaded whenever the State above it changes. Feeds the City screen.",
  "No financial effect - addressing and territory reporting only."],

 ["2.6", "City", "mst_city.php", "Lookup (address level 3)",
  "Cities, each belonging to one district. The bottom level.",
  "mst_city (RW)\nmst_district (R)\nmst_state (R)",
  "INSERT mst_city (city_name, district_id, state_id, country_id).\nUPDATE on edit.\nDELETE: UPDATE city_status = 0.",
  "1. Open - live cities listed with their district.\n2. Choose District, type City, Save.\n3. In an address block, choosing a district calls inc/cis_ajax/jquery_select_city.php to refill this dropdown.",
  "The City dropdown on every address block.",
  "A soft-deleted city disappears from new dropdowns but stays on old documents (the document stored the id and the print reads it back without checking status). Editing a customer pointed at a deleted city shows the box empty, and saving blanks it. Prefer renaming to deleting."],

 ["2.7", "Department", "mst_department.php", "Lookup",
  "The departments employees belong to. Top of the two-level org structure.",
  "mst_department (RW)",
  "INSERT mst_department (department_name, created_by, created_dtm).\nUPDATE on edit.\nDELETE: UPDATE rec_del_status = 0.",
  "1. Open - live departments listed.\n2. Type the name, Save.\n3. Edit loads it back for renaming.\n4. Now selectable in the Employee form and as a filter on the staff and labour lists.",
  "Employee - the Department dropdown; Designation - designations hang off a department; salary and attendance reports group by it.",
  "Status column is rec_del_status, not department_status - the naming differs from the address tables.\nSoft delete leaves employees pointing at it; they show a blank department. Move them first."],

 ["2.8", "Designation", "mst_designation.php", "Lookup (child of Department)",
  "Job titles. Each one belongs to ONE department, so the Designation dropdown on the employee form only shows titles for the department already chosen.",
  "mst_designation (RW)\nmst_department (R)",
  "INSERT mst_designation (department_id, designation_name, created_by, created_dtm).\nUPDATE both on edit - it can be moved to another department.\nDELETE: UPDATE rec_del_status = 0.",
  "1. Open - live designations with their department.\n2. Choose Department, type Designation, Save.\n3. Edit lets you rename or re-parent.\n4. On the Employee form, choosing a department filters this dropdown.",
  "Employee - the Designation dropdown; printed on salary documents; the staff and labour list columns.",
  "The same title in two departments is two different ids, so reports grouping by id show them separately."],

 ["2.9", "Month Master", "mst_month_master.php (list) > mst_month_master_add.php (add/edit)",
  "Setup - THE PAYROLL CALENDAR",
  "One row per month: total days, WORKING DAYS, holidays and function holidays. The working-days figure is the divisor payroll uses. A month with no row, or the wrong count, gives every salary for that month the wrong value.",
  "tbl_month_master (RW)",
  "INSERT tbl_month_master (month, year, total_days, working_days, holidays, function_holidays, created_by, created_dtm).\nUPDATE the same figures plus modify_by, modify_dtm.\nDELETE: UPDATE month_master_status = 0.",
  "1. Masters > Month Master - month name and year, newest first.\n2. New Month opens mst_month_master_add.php.\n3. Pick month and year, enter total days, working days, holidays, function holidays.\n4. Save - first checks no ACTIVE row already exists for that month and year, so September 2025 cannot be entered twice.\n5. Edit works the same, excluding the row being edited from the duplicate check.",
  "All four attendance reports (PF, Without PF, OT, EPF) read this row for the month you pick; Employee Salary - the per-day rate is the monthly salary divided by working_days; the month dropdown on the attendance screens is built from these rows.",
  "NO ROW, NO SALARY. The attendance screens list only the months that exist here, so forgetting next month silently BLOCKS payroll rather than warning anyone.\nCHANGING working_days AFTER salaries are calculated CHANGES PAST FIGURES - the reports recalculate from this row every time they open; nothing is frozen.\nmonth is stored as a NUMBER 1-12; the list turns it into a name.\ntotal_days, holidays and function_holidays are stored but do not drive the pay calculation, and nothing checks that they add up."],
]

HR = [
 ["3.1", "Employee",
  "mst_employee_add.php (2,500 lines - list, add and edit) > inc/cis_ajax/jquery_select_emp_code.php (the code) > inc/cis_ajax/jquery_modal_employee_det.php (view)",
  "Master - THE LARGEST FORM IN BIE",
  "Everything about one person: name, father's/husband's name, DOB, blood group, photo, both addresses, bank account, PAN, Aadhaar, marital and family details, joining date, EPF and UAN, nominee, scanned proofs. It also creates their accounts LEDGER, optionally their LOGIN, and records the ASSETS issued to them and their CERTIFICATES.",
  "mst_employee (RW)\nmst_ledger (W - FIRST)\nmst_accounts_group (R)\ntbl_user (W - a login, if ticked)\ntbl_asset_details (RW)\nmst_employee_certificate (RW - Staff only)\nmst_department / mst_designation (R)\nmst_labour (R)\nmst_branch (R)\nmst_state / mst_district / mst_city (R - twice)",
  "INSERT mst_ledger FIRST -> capture ledger_id.\nINSERT mst_employee - one row, ~65 columns, including branch_id, emp_code, emp_slno, emp_type, ledger_id, emp_advance_bal, created_by, created_dtm.\nINSERT tbl_asset_details - one row per asset. ON EDIT every existing row for this employee is DELETED first, then re-inserted.\nINSERT mst_employee_certificate - one per certificate, ONLY when emp_type = 1 (Staff). Also delete-then-reinsert on edit.\nINSERT tbl_user - a login when login access is ticked (usr_logname, hashed usr_logpwd, branch_id, emp_id).\nEDIT: UPDATE mst_employee + mst_ledger + tbl_user together.\nDELETE: UPDATE mst_employee SET rec_del_status = 0 via jquery_delete_records_hr.php. THE LEDGER AND THE LOGIN STAY ACTIVE.",
  "1. HR Management > Employee, or reach the form from the Staff or Labour list.\n2. Choose EMPLOYEE TYPE first - Staff (1), Labour (2) or Others (3). Sections appear and disappear as you do.\n3. Choose BRANCH and employment status (Temporary / Permanent). The screen then calls jquery_select_emp_code.php and fills in the read-only EMPLOYEE CODE.\n4. Personal details, current address, permanent address - or tick copy address.\n5. Bank details, PAN, Aadhaar, uploaded proofs (each renamed using the employee code, stored under project_img/).\n6. Joining date, EPF and UAN, nominee, credit days, pay mode.\n7. Accounts group and opening balance for the ledger.\n8. ASSETS issued - asset, issue date, quantity, value; for a SIM, the number and its limit. CERTIFICATES if Staff.\n9. Tick LOGIN ACCESS and give a login name and password if they need to sign in.\n10. Save - ledger, employee, assets, certificates, login, in that order.\n11. You land on the Staff list, the Labour list, or lst_employee.php, by type.",
  "Labour list and Staff list (the same rows split by type); Employee Salary (CTC); Employee Advance and Employee Debit Note; Import Attendance - punches are matched by bio_id; all four attendance and salary reports; Accounts - Day Book, Ledger Book, Trial Balance via ledger_id; Settings > User - the login created here appears there too.",
  "DELETING AN EMPLOYEE DOES NOT DISABLE THEIR LOGIN - rec_del_status goes to 0 but tbl_user.usr_status stays 1 and they can still sign in. Delete them in Settings > User as well.\nASSETS AND CERTIFICATES ARE REBUILT ON EVERY EDIT (delete-all then re-insert). If the form does not post them back, they are gone. Check after any edit.\nCERTIFICATES ARE STAFF-ONLY - the insert is guarded by emp_type == 1 and silently dropped for Labour or Others.\nbio_id is the link to attendance, is free text, and has NO uniqueness check. Duplicates share punches; a missing one means the person never appears in an attendance report.\nemp_type = 3 (Others) lands on lst_employee.php, which is not on any menu - those rows are effectively invisible.\nemp_code = BIE / branch / type+status / serial, e.g. BIE/HO/SP/42 (S Staff, L Labour, O Others; T Temporary, P Permanent).\nSame plain-text pw_hint problem as Settings > User."],

 ["3.2", "Labour", "lst_labour.php + inc/datatable/ajaxLabourList.php", "List (filtered view)",
  "The employee list filtered to emp_type = 2. Nothing else differs from the Staff list.",
  "mst_employee (R)\nmst_department (R)\nmst_designation (R)",
  "Nothing of its own. Add and edit open the Employee form. The dustbin calls inc/cis_ajax/jquery_delete_records_hr.php to set rec_del_status = 0.",
  "1. HR Management > Labour - active labour employees.\n2. Narrow by branch or department; search matches name, code, mobile, department, designation.\n3. The eye icon opens jquery_modal_employee_det.php - the full record read-only, in a modal, without leaving the list.\n4. The pencil opens mst_employee_add.php for that person.",
  "Nothing writes from here. It is the way into the Employee form for labour.",
  "Branch visibility is the same as the supplier list: user id 1 or anyone at Head Office sees every branch; everyone else sees only their own."],

 ["3.2", "Staff", "lst_staff.php + inc/datatable/ajaxStaffList.php", "List (filtered view)",
  "The employee list filtered to emp_type = 1. Identical to the Labour list in every other way.",
  "mst_employee (R)\nmst_department (R)\nmst_designation (R)",
  "Nothing of its own - same delete endpoint as the Labour list.",
  "1. HR Management > Staff - active staff.\n2. Same filters, same search, same modal view, same edit route.",
  "Nothing writes from here.",
  "THERE IS NO THIRD LIST FOR emp_type = 3 (Others). Those rows exist in mst_employee but appear on neither list. If headcount looks low, count the emp_type = 3 rows."],

 ["3.2.1", "Labour Master", "mst_labour.php", "Lookup",
  "The names of labour groups or contractors an employee can be attached to. One field.",
  "mst_labour (RW)",
  "INSERT mst_labour (labour_name, created_by, created_dtm).\nUPDATE on edit.\nDELETE: UPDATE rec_del_status = 0.",
  "1. Open - live labour groups listed.\n2. Type the name, Save.\n3. Edit loads it back.",
  "Employee - the Labour dropdown, shown when the employee type is Labour. Attendance and salary reports can be grouped by it.",
  "mst_labour still carries a company_id column left over from the Benzear codebase this one was forked from. BIE is organised by BRANCH, not company, and nothing reads it."],

 ["3.3", "Salary Package",
  "lst_salary_package.php (list) > mst_salary_package_add.php (add/edit) > inc/datatable/ajaxSalaryPackageList.php",
  "Master - pay structures",
  "How a salary is SPLIT UP - what share is basic, DA, HRA, conveyance and CCA, and what rate of PF applies. The six figures are PERCENTAGES, NOT AMOUNTS: the shipped packages all read 40, 25, 25, 10, 12. The amount itself lives on the employee (3.4). By convention packages are NAMED after the CTC they go with - 18000, 20000 - but that is a habit, not something the code reads.",
  "mst_salary_setting (RW)",
  "INSERT mst_salary_setting (sal_package_name, sal_type, sal_period, sal_basic, sal_da, sal_hra, sal_convey, sal_pf, sal_cca, created_by, created_dtm).\nUPDATE the same plus modify_by, modify_dtm.\nDELETE: UPDATE rec_del_status = 0.",
  "1. HR Management > Salary Package - name, type and the percentages.\n2. Add New opens mst_salary_package_add.php.\n3. Name it, choose Monthly (M) or Daily (D), set the period, enter the six PERCENTAGES.\n4. Save - one row, straight in.\n\nHOW THEY ARE USED: basic = earned x sal_basic%, and the same for DA, HRA and conveyance; then EPF = (basic + DA) x sal_pf%. The percentages decide the SPLIT and the PF DEDUCTION, never the total.",
  "The salary package dropdown on the employee screens; Attendance Report (PF) and (Without PF) - the components come from here and are apportioned by days worked; EPF Report, through sal_pf.",
  "sal_period IS THE FIELD THAT MATTERS: 2 means the CTC is a MONTHLY figure, so earned pay is CTC / working days x days paid; anything else means the CTC is a DAILY RATE, so earned pay is CTC x days paid. sal_type (M/D) is only a label - the calculation does not read it.\nNOTHING CHECKS THAT THE PERCENTAGES ADD UP TO 100. Enter figures summing to 90 and the payslip shows components that do not add up to the net - no warning, no error.\nEDITING A PACKAGE CHANGES PAY FOR EVERYBODY ON IT, INCLUDING PAST MONTHS - the reports read the current row each time they open; nothing is frozen at month end. To change one person's pay, change their CTC in Employee Salary Setting, which IS versioned; only change a package when the SPLIT itself is wrong."],

 ["3.4", "Employee Salary Setting",
  "employee_salary.php (list) > emp_setsalary.php (THE ACTUAL SETTING SCREEN) > inc/datatable/ajaxEmployeeSalarySet.php > modal_employee_det.php",
  "Versioned transaction - WITHOUT A ROW HERE, AN EMPLOYEE HAS NO PAY",
  "The list answers 'what is everyone on?' - code, name, department, designation, CTC. Click through and you set the employee's CTC, the salary package that says how it splits, their OT rate, their casual leave, and the date it takes effect. Saving does NOT overwrite - it retires the old row and writes a new one.",
  "tbl_emp_salary (RW - one row per revision, live one flagged em_current = 1)\nmst_employee (W - emp_ctc and em_id cached onto the employee row)\nmst_salary_setting (R - the package dropdown)\nmst_department / mst_designation (R)",
  "UPDATE tbl_emp_salary SET em_current = 0 WHERE emp_id = <this employee> - RETIRES the old revision, does not delete it.\nINSERT tbl_emp_salary (emp_id, sal_id, emp_ctc, emp_ot_sal, emp_cl, is_allow_fh, em_from, em_current = 1, em_remarks, em_update_by, em_date_time).\nUPDATE mst_employee SET emp_ctc = :emp_ctc, em_id = :em_id - a cached copy pointing at the new current revision.",
  "1. HR Management > Employee Salary Setting. Search by name, code, mobile, department or designation; filter by branch and employee type.\n2. Click through to emp_setsalary.php for one employee - current figures plus the full history of past revisions.\n3. Enter the new CTC, choose the SALARY PACKAGE, set the OT rate, the casual leave figure and whether function holidays are allowed; give the effective-from date and a remark.\n4. Save - old rows retired, new row inserted, mst_employee pointed at it.\n5. The new CTC is used by the next attendance report you run.",
  "Attendance Report (PF) and (Without PF) - earned pay is CTC / working days x days paid, then split by the package percentages; OT Report via emp_ot_sal; EPF Report - PF is a percentage of basic + DA, both derived from this CTC; this list; the employee's own record.",
  "AN EMPLOYEE WITH NO ROW HERE IS PAID NOTHING. The Employee form does not ask for CTC, so a new employee has none until someone comes to this screen. The attendance reports list them with zeros rather than warn you.\nTWO COPIES OF THE CTC EXIST and are written together: the real one on the current tbl_emp_salary row, and a cached copy on mst_employee.emp_ctc. The list shows the cached copy; the payroll reports read the real one. A direct database edit to mst_employee.emp_ctc changes what you see and not what is paid.\nTHIS IS THE em_current PATTERN - never overwrite, retire the old row and insert a new one, then cache the pointer on the parent. tbl_emp_advance and tbl_emp_debit_note use the same idea with is_current."],

 ["3.5", "Employee Advance",
  "employee_advance.php (list) > emp_advance_update.php (record) > emp_advance_return_payment.php (recover) > inc/datatable/ajaxEmployeeAdvance.php",
  "Transaction - posts to accounts",
  "Money paid to an employee ahead of salary. The list shows advanced, returned and balance per employee. Recording an advance posts a real accounts entry. RECOVERY IS NOT DONE HERE - it happens from the attendance reports, deducted from that month's net pay.",
  "tbl_emp_advance (RW)\ntbl_emp_advance_return_payment (W)\ntbl_accounts (W - THE CENTRAL JOURNAL)\nmst_employee (R - and its ledger_id)\nmst_finyear (R)",
  "INSERT tbl_emp_advance (emp_id, advance_slno = MAX+1 within pay_finyr, advance_date, advance_amount, balance_amount = the full amount, pay_finyr, ledger_id, pay mode and cheque fields, is_current = 1, advance_status = 1). chq_passed starts as 'NO' when pay_type = 'Q'.\nINSERT tbl_accounts (voucher_type = 'Employee Advance', record_type = 'M', advance_id = the new row, dr_ledger_id = the EMPLOYEE'S ledger, cr_ledger_id = the cash/bank ledger).\nRECOVERY: INSERT tbl_emp_advance_return_payment (with atten_month and atten_year); UPDATE tbl_emp_advance SET return_amount = return_amount + paid, balance_amount = balance_amount - paid, advance_status = 3; INSERT the reverse tbl_accounts row.",
  "1. HR Management > Employee Advance - every employee with advanced / returned / balance.\n2. Modify Advance opens emp_advance_update.php for that person.\n3. Date, amount, payment mode (cash / cheque / card / transfer) with cheque number or reference, and a remark.\n4. Save - the advance row, then the accounts entry.\n5. TO RECOVER: go to the attendance report for the month, find the employee, use the Advance Deduction (+) link. That opens emp_advance_return_payment.php already knowing the month, the year and the net pay.\n6. Enter how much to recover - instalment row, balance reduced, reverse accounts entry.",
  "Day Book, Ledger Book, Trial Balance via tbl_accounts; the employee's own ledger (a debit until recovered); Attendance Report (PF) and (Without PF) - the advance deduction column and the (+) link; this list, recalculated from tbl_emp_advance on every load.",
  "A PART-RECOVERY MARKS THE ADVANCE SETTLED: advance_status is set to 3 whatever the amount. Recovering 1,000 of 5,000 flags it done. The list still shows it (it does not filter on status) but the balance calculation inside emp_advance_update.php excludes status 3 - so the two disagree. TRUST balance_amount ON THE LIST.\nNO WAY TO CORRECT OR CANCEL from the screen - the only action is Save, which adds another row and another journal entry.\nchq_passed is set to 'NO' for a cheque and NEVER UPDATED - nothing marks a cheque cleared."],

 ["3.6", "Employee Debit Note",
  "employee_debit_note.php (list) > emp_debit_note.php (raise) > inc/datatable/ajaxEmployeeDebit.php",
  "Transaction - posts to accounts",
  "An amount charged AGAINST an employee: damage, shortfall, penalty, the cost of something lost. Structurally the mirror image of Employee Advance, and posts to accounts the same way. The difference is intent - an advance is lent, a debit note is owed.",
  "tbl_emp_debit_note (RW)\ntbl_accounts (W)\nmst_employee (R - and its ledger_id)\nmst_finyear (R)",
  "INSERT tbl_emp_debit_note (emp_id, serial within pay_finyr, date, amount, balance_amount, pay_finyr, ledger_id, reason, is_current = 1, debit_status).\nINSERT tbl_accounts - the double-entry row for the charge.\nRECOVERY: UPDATE tbl_emp_debit_note SET return_amount up, balance_amount down.",
  "1. HR Management > Employee Debit Note - every employee with debited / returned / balance.\n2. Modify Debit opens emp_debit_note.php for that person.\n3. Date, amount, reason and the ledger the charge goes against.\n4. Save - the debit row and the matching accounts entry.\n5. Recovery is handled from the attendance reports when the month's pay is calculated.",
  "Day Book, Ledger Book, Trial Balance; the employee's ledger; Attendance Report (PF) and (Without PF) - the deduction column; this list.",
  "THE SAME CAVEATS AS EMPLOYEE ADVANCE (3.5) - the two screens share their code: a part-recovery can mark it settled (debit_status = 3), there is no cancel or correct, and the list and the entry screen can disagree.\nA debit note is a real accounting charge, not a note to self - it hits the employee's ledger and the Trial Balance the moment you save."],

 ["3.7", "Shift Wise", "shift_wise.php (list) > shift_wise_time_setting.php (edit the times)",
  "Setup - THE RULES ATTENDANCE IS JUDGED AGAINST",
  "Two shifts, DAY and NIGHT, and the clock times that define each. The official check_in and check_out are what the attendance import measures lateness against. Each row ALSO carries a window around each time, a duration, and a next-day flag - they are on the form and they save, but NOTHING READS THEM.",
  "mst_shifts (RW - update only)",
  "UPDATE mst_shifts SET check_in, check_out, check_in_start, check_in_end, check_out_start, check_out_end, duration, work_day, is_nxtday_checkout WHERE shift_id = <the one you edited>. THAT IS THE ONLY WRITE THIS SCREEN MAKES - there is no insert and no delete.",
  "1. HR Management > Shift Wise - two rows, DAY and NIGHT.\n2. The pencil opens shift_wise_time_setting.php for that shift.\n3. Adjust the official check-in and check-out, then the check-in window (check_in_start to check_in_end) and the check-out window (check_out_start to check_out_end).\n4. Set duration in MINUTES - the length of a full shift - and whether check-out falls on the NEXT DAY.\n5. Update. You cannot add or delete a shift here.",
  "Import Attendance - after pairing punches into a check-in and a check-out it reads this row and works out late_in, late_out, early_in and early_out in MINUTES; Attendance Report (PF) and (Without PF) - those minutes feed present, absent and half-day; OT Report - overtime is derived from the recorded work time.",
  "SIX OF THE EIGHT FIELDS ON THIS FORM DO NOTHING. The import fetches the shift row and uses ONLY check_in and check_out, to work out how many minutes late or early someone was. The four window fields are fetched in the same query and never looked at; duration and work_day are read by nothing; and NO FILE IN BIE READS is_nxtday_checkout AT ALL. Changing them is harmless and pointless.\nTHE NIGHT SHIFT IS NEVER ASSIGNED: import_attendance.php sets shift_id = 1 for every punch, so everyone is treated as DAY shift whatever time they worked. A night worker checking in at 19:00 is measured against DAY's 09:00 start and comes out enormously late. Until the import chooses a shift, editing the NIGHT row changes nothing.\nCHANGING check_in OR check_out CHANGES ATTENDANCE ALREADY IMPORTED - the late and early minutes are recalculated whenever a row is reprocessed.\nShipped data: DAY 09:00-17:30 duration 510; NIGHT 19:00-07:00 duration 540."],
]

